export function mount(root) {
let disposed=false;
root.innerHTML='<div id="app"></div><dialog id="drawer" aria-labelledby="dialog-title"></dialog><dialog id="modal" aria-labelledby="modal-title"></dialog><div id="toast" role="status" aria-live="polite"></div>';
async function scopedFetch(path, options={}) {
let session;try {session=JSON.parse(sessionStorage.getItem('sigpmf_sessao')||'null');}catch{}
const response=await fetch('/api/plano-governo'+path.replace(/^\/api/,''),{...options,headers:{...options.headers,...(session?.token?{Authorization:'Bearer '+session.token}:{})}});
if(response.status===401){sessionStorage.removeItem('sigpmf_sessao');window.dispatchEvent(new Event('sigpmf:sair'));}
return response;
}
const $=s=>root.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',plan:'<path d="M9 5H5v16h14V5h-4"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="m8 12 1 1 2-2m2 1h3m-8 5h8"/>',projects:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18m-11 0v3h4v-3"/>',departments:'<path d="M4 21V5h10v16m0-11h6v11M2 21h20M7 9h4m-4 4h4m-4 4h4m6-3h1m-1 3h1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h2m4 0h2"/>',alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3h.01"/>',history:'<path d="M3 11a9 9 0 1 1 3 8M3 4v7h7m2-4v6l4 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',refresh:'<path d="M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>',link:'<path d="m10 13 4-4m-5-2 3-3a4 4 0 0 1 6 6l-3 3m0 4-3 3a4 4 0 0 1-6-6l3-3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',print:'<path d="M7 8V3h10v5M7 17H3V9h18v8h-4M7 14h10v7H7Z"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15l-1 5Z"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',flag:'<path d="M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.plan}</svg>`;
let boardMode='table'; let weekFrom='',weekTo='';
let store=null,view='overview',detailId='',filters={q:'',department:'',status:'',research:'',scope:'all'},page=1,busy=false,toastTimer;
const statusNames={em_validacao:'A validar',planejado:'Planejado',em_andamento:'Em andamento',bloqueado:'Bloqueado',concluido:'Concluído',a_validar:'A validar',planejada:'Planejada',parcial:'Parcialmente cumprido',cumprida:'Cumprimento validado'};
const roleNames={admin:'Administrador SIGPMF',gestor:'Gestão de governo',prefeito:'Gabinete · acompanhamento',secretaria:'Secretaria',leitura:'Consulta'};
const tone=s=>({em_validacao:'purple',planejado:'neutral',em_andamento:'blue',bloqueado:'red',concluido:'green',cumprida:'green',parcial:'amber',a_validar:'neutral',planejada:'neutral'}[s]||'neutral');
const badge=(label,t='neutral')=>`<span class="tag ${t}">${esc(label)}</span>`;
const datefmt=x=>x?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(x.length===10?x+'T15:00:00Z':x)):'Sem prazo';
const brl=x=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(x||0);
const localDay=x=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date(x));
const today=()=>localDay(new Date());
const dateTime=x=>!x?'Sem atualização de gestão':new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(x));
const dep=id=>store.state.departments.find(x=>x.id===id);const person=id=>store.state.people.find(x=>x.id===id);const active=()=>store.state.projects.filter(p=>!p.archived);
const related=c=>active().filter(p=>p.commitmentIds.includes(c.id));
const admin=()=>['admin','gestor'].includes(store.user.role);const canEdit=p=>admin()||(store.user.role==='secretaria'&&(store.user.departmentIds.includes(p.departmentId)||person(p.ownerId)?.email?.toLowerCase()===store.user.email.toLowerCase()));
const overdue=p=>!!p.due&&p.due<today()&&p.status!=='concluido'&&!p.archived;
const stale=p=>p.status!=='concluido'&&!p.archived&&p.updatedAt&&(Date.now()-Date.parse(p.updatedAt))>15*86400000;
const cp=c=>{let ps=related(c).filter(p=>p.progress!==null);return ps.length?Math.round(ps.reduce((a,p)=>a+p.progress,0)/ps.length):null;};
const btn=(label,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(title,desc,button='',ico='projects')=>`<div class="empty">${icon(ico)}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${button}</div>`;
function toast(message,error=false){if(disposed)return;clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className='visible'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',6500);}
async function reload(){const response=await scopedFetch('/api/state',{cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||data.detail||'Não foi possível carregar.');store=data;return data;}
async function mutate(action,data){if(busy)return false;busy=true;root.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{const res=await scopedFetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:store.version,action,data})});const out=await res.json();if(!res.ok){if(res.status===409)toast('Outra pessoa atualizou os dados. Feche o formulário, recarregue e revise antes de salvar.',true);throw Error(out.error||out.detail||'Não foi possível salvar.');}await reload();return true;}finally{busy=false;root.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}}
function navTo(v,id=''){location.hash=v+(id?'/'+id:'');}
function route(){if(disposed)return;const parts=location.hash.slice(1).split('/');view=parts[0]||'overview';detailId=parts[1]||'';filters={q:'',department:'',status:'',research:'',scope:'all'};page=1;render();window.scrollTo(0,0);}
const pageNames={overview:'Visão do prefeito',commitments:'Compromissos',projects:'Projetos',departments:'Secretarias',agenda:'Agenda de entregas',alerts:'Pontos de atenção',history:'Histórico',settings:'Cadastros e acessos',project:'Detalhe do projeto'};
function render(){if(!store||disposed)return;const tabs=[['overview','Visão do prefeito'],['commitments','Compromissos'],['projects','Quadro de projetos'],['weekly','Evolução semanal'],['departments','Secretarias'],['agenda','Agenda'],['alerts','Pontos de atenção'],['history','Histórico'],...(admin()?[['settings','Responsáveis']]:[])];
$('#app').innerHTML=`<nav class="pg-subnav" aria-label="Plano de Governo">${tabs.map(([key,label])=>`<a href="#${key}" ${view===key?'aria-current="page"':''}>${label}</a>`).join('')}<button class="icon-btn" data-action="reload" aria-label="Atualizar plano">${icon('refresh')}</button></nav><div class="pg-page">${body()}</div>`;
if(view==='commitments'||view==='projects')renderRows();
}

function heading(title,desc,actions='',eyebrow='Plano de Governo · 2025–2028'){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></div>`;}
const createButton=(id='')=>!['prefeito','leitura'].includes(store.user.role)?btn(icon('plus')+'Novo projeto','new-project','',id?`data-id="${id}"`:''):'';
const kpi=(label,value,foot,i)=>`<div class="kpi"><div class="kpi-top">${label}${icon(i)}</div><div class="kpi-value mono">${value}</div><div class="kpi-foot">${foot}</div></div>`;
const panel=(title,sub,content,action='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div><div class="panel-body">${content}</div></section>`;
function body(){switch(view){case'overview':return overview();case'weekly':return weekly();case'commitments':return commitments();case'projects':return projects();case'departments':return departments();case'project':return projectDetail();case'agenda':return agenda();case'alerts':return alerts();case'history':return history();case'settings':return settings();default:return overview();}}
function overview(){const cs=store.state.commitments,ps=active(),linked=cs.filter(c=>related(c).length).length,measured=ps.filter(p=>p.progress!==null),documented=ps.filter(p=>p.origin==='pesquisa_publica'),delivered=cs.filter(c=>c.researchStatus==='Entrega comprovada').length,validated=cs.filter(c=>c.validation==='cumprida').length;
const since=shiftDay(today(),-7);const moved=new Set((store.state.snapshots||[]).filter(x=>localDay(x.date)>=since&&x.progress!==null).map(x=>x.projectId));
const counts=['em_validacao','planejado','em_andamento','bloqueado','concluido'].map(st=>({st,n:ps.filter(p=>p.status===st).length}));
const areas=[...new Set(cs.map(c=>c.area))];const axes=areas.map(area=>{const items=cs.filter(c=>c.area===area),covered=items.filter(c=>related(c).length).length,docs=items.filter(c=>c.sources.length).length;return `<div class="axis modern-axis"><div><span class="axis-name">${esc(area)}</span><div class="axis-sub">${covered} com iniciativas · ${docs} com referências</div><div class="track"><span style="width:${100*covered/items.length}%"></span></div></div><div class="axis-total mono">${items.length}<small>compromissos</small></div></div>`}).join('');
const recent=uniqueDocuments().filter(e=>e.date).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);
return heading('O plano em movimento.','Decisões claras, responsáveis definidos e entregas acompanhadas semana a semana.',btn(icon('download')+'Exportar dados','export','secondary')+createButton())+`<div class="pg-context"><span>${badge(cs.length+' compromissos','blue')} ${badge(areas.length+' eixos')} ${badge(validated+' validados pela gestão','green')}</span><span class="muted small">Gestão 2025–2028 · Base documental de 23/11/2026</span></div><div class="kpis modern-kpis">${kpi('Iniciativas documentadas',documented.length,`${linked} compromissos com projetos vinculados`,'projects')}${kpi('Entregas identificadas',delivered,'Evidência pública · sujeita à validação','check')}${kpi('Projetos com medição',measured.length,'Avanço físico registrado pela equipe','target')}${kpi('Atualizados nesta semana',moved.size,'Com medição nos últimos 7 dias','history')}</div><div class="grid executive-grid">${panel('A carteira de entregas','Situação de acompanhamento dos projetos. A documentação inicial não atribui avanço físico.',`<div class="portfolio-strip">${counts.filter(c=>c.n).map(c=>`<span class="strip-${c.st}" style="flex:${c.n}" title="${statusNames[c.st]}: ${c.n}"></span>`).join('')}</div><div class="status-legend">${counts.map(c=>`<button data-action="board-status" data-status="${c.st}"><i class="strip-${c.st}"></i><span>${statusNames[c.st]}</span><b>${c.n}</b></button>`).join('')}</div><div class="executive-callout">${icon('info')}<div><b>Da evidência à entrega validada</b><p>${ps.filter(p=>p.status==='em_validacao').length} iniciativas aguardam confirmação de escopo, responsável, prazo e medição pela secretaria.</p>${btn('Abrir quadro de trabalho','go-projects','ghost')}</div></div>`,btn('Ver quadro','go-projects','ghost'))}${panel('A semana em foco','Movimentação real registrada no sistema.',`<div class="week-focus"><div><b>${(store.state.snapshots||[]).filter(x=>localDay(x.date)>=since).length}</b><span>atualizações de projeto</span></div><div><b>${ps.filter(p=>p.status==='bloqueado').length}</b><span>impedimentos abertos</span></div><div><b>${ps.filter(overdue).length}</b><span>prazos vencidos</span></div></div><p class="muted small">A evolução semanal começa com as medições das equipes. O histórico de publicações permanece separado e pode ser consultado desde já.</p>${btn('Comparar períodos','go-weekly','secondary')}`)}</div><div class="grid executive-grid">${panel('O que já tem documentação','Referências mais recentes associadas às iniciativas.',recent.map(e=>`<div class="document-feed"><span class="doc-date">${datefmt(e.date)}</span><div><button class="text-action" data-action="open-project" data-id="${e.projectId}">${esc(e.title)}</button><small>${esc(e.kind)}</small></div><a href="${esc(e.url)}" target="_blank" rel="noopener" aria-label="Abrir fonte: ${esc(e.title)}">${icon('link')}</a></div>`).join(''))}${panel('Cobertura por eixo','Compromissos organizados em iniciativas; não é percentual de cumprimento.',axes)}</div><div class="notice">${icon('info')}<p><b>Referências carregadas, sem progresso inventado.</b> As iniciativas documentais são uma organização inicial da pesquisa, não substituem o cadastro de projetos e contratos oficiais. A secretaria confirma as informações; o gabinete valida o cumprimento dos compromissos.</p></div>`;
}

function filterToolbar(type){return `<div class="toolbar"><label class="search"><span class="sr-only" hidden>Buscar ${type==='commitments'?'compromissos':'projetos'}</span>${icon('search')}<input id="search" aria-label="Buscar ${type==='commitments'?'compromissos':'projetos'}" placeholder="${type==='commitments'?'Buscar por compromisso ou área…':'Buscar por projeto ou responsável…'}" value="${esc(filters.q)}" data-filter="q"></label><select class="filter-select" aria-label="Filtrar por secretaria" data-filter="department"><option value="">Todas as secretarias</option>${store.state.departments.map(d=>`<option value="${d.id}" ${filters.department===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select class="filter-select" aria-label="Filtrar por situação" data-filter="status"><option value="">Todas as situações</option>${(type==='commitments'?['a_validar','planejada','em_andamento','parcial','cumprida']:['em_validacao','planejado','em_andamento','bloqueado','concluido']).map(s=>`<option value="${s}" ${filters.status===s?'selected':''}>${statusNames[s]}</option>`).join('')}</select>${type==='commitments'?`<select class="filter-select" aria-label="Filtrar cobertura de projetos" data-filter="scope"><option value="all">Todos os compromissos</option><option value="missing">Sem projetos</option><option value="linked">Com projetos</option></select>`:''}</div>`;}
function commitments(){return heading(`${store.state.commitments.length} compromissos. Um plano integrado.`,'Vincule projetos a cada item e acompanhe o cumprimento com evidências.',btn(icon('download')+'Exportar','export','secondary')+createButton())+`<section class="panel">${filterToolbar('commitments')}<div id="rows"></div></section><p class="export-note">O andamento de gestão é independente da pesquisa documental inicial. A validação de cumprimento exige projetos concluídos, justificativa e evidência.</p>`;}
function projects(){return heading('Quadro de projetos.','Organize por secretaria, acompanhe entregas e mantenha a próxima ação sempre à vista.',createButton())+`<div class="board-viewbar"><div class="view-switch">${['table','kanban'].map(mode=>`<button data-action="board-mode" data-mode="${mode}" class="${boardMode===mode?'selected':''}">${icon(mode==='table'?'plan':'dashboard')}${mode==='table'?'Quadro principal':'Kanban'}</button>`).join('')}</div><span class="muted small">${active().length} iniciativas · fontes preservadas em cada projeto</span></div><section class="panel board-panel">${filterToolbar('projects')}<div id="rows"></div></section>`;}

function filtered(){const norm=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let rows=view==='commitments'?store.state.commitments:active();return rows.filter(r=>{if(filters.department&&r.departmentId!==filters.department)return false;if(filters.status&&(view==='commitments'?r.validation:r.status)!==filters.status)return false;if(view==='commitments'&&filters.scope!=='all'&&Boolean(related(r).length)!==(filters.scope==='linked'))return false;return !filters.q||norm([r.title,r.area,dep(r.departmentId)?.name,person(r.ownerId)?.name,r.id].join(' ')).includes(norm(filters.q));});}
function renderRows(){const container=$('#rows');if(!container)return;const rows=filtered();if(view==='projects'){container.innerHTML=board(rows);return;}const per=12,max=Math.max(1,Math.ceil(rows.length/per));page=Math.min(page,max);const shown=rows.slice((page-1)*per,page*per);if(!rows.length){container.innerHTML=empty('Nenhum resultado encontrado','Ajuste a busca ou os filtros.',btn('Limpar filtros','clear-filters','secondary'),'search');return;}
container.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Item do plano</th><th>Secretaria de referência</th><th>Projetos</th><th>Gestão / validação</th><th></th></tr></thead><tbody>${shown.map(commitmentRow).join('')}</tbody></table></div><div class="table-footer"><span>${(page-1)*per+1}–${Math.min(page*per,rows.length)} de ${rows.length} compromissos</span><div class="actions">${btn('Anterior','prev','secondary',page===1?'disabled':'')}<span>Página ${page} de ${max}</span>${btn('Próxima','next','secondary',page===max?'disabled':'')}</div></div>`;}

function commitmentRow(c){const ps=related(c),progress=cp(c);return `<tr><td class="table-title"><span class="code mono">PG-${String(c.id).padStart(3,'0')}</span><br><button data-action="open-commitment" data-id="${c.id}">${esc(c.title)}</button><small>${esc(c.area)}</small></td><td>${esc(dep(c.departmentId)?.name||'A definir')}</td><td>${ps.length?`<b class="mono">${ps.length}</b> ${ps.length===1?'projeto':'projetos'}<small class="muted" style="display:block">${progress===null?'Avanço a validar':progress+'% de avanço médio medido'}</small>`:badge('Sem projeto','amber')}</td><td>${badge(statusNames[c.validation],tone(c.validation))}</td><td><button class="icon-btn" data-action="open-commitment" data-id="${c.id}" aria-label="Abrir compromisso ${c.id}">${icon('chevron')}</button></td></tr>`;}
function progressCell(p){return p.progress===null?'<span class="unmeasured">Avanço a validar</span>':`<span class="progress-number">${p.progress}%</span><div class="track tiny-track"><span style="width:${p.progress}%"></span></div>`;}
function board(rows){if(!rows.length)return empty('Nenhum projeto neste filtro','Ajuste os filtros ou crie uma iniciativa.',createButton(),'projects');if(boardMode==='kanban')return `<div class="kanban">${['em_validacao','planejado','em_andamento','bloqueado','concluido'].map(st=>`<section class="kanban-column" data-drop-status="${st}"><div class="kanban-heading"><i class="strip-${st}"></i><b>${statusNames[st]}</b><span>${rows.filter(p=>p.status===st).length}</span></div>${rows.filter(p=>p.status===st).map(p=>`<article class="kanban-card" draggable="${canEdit(p)}" data-project-drag="${p.id}"><button class="text-action" data-action="open-project" data-id="${p.id}">${esc(p.title)}</button><p>${esc(dep(p.departmentId)?.name||'Secretaria a definir')}</p>${progressCell(p)}<div class="kanban-card-foot">${avatar(person(p.ownerId)?.name)}<span>${p.evidence.length} fontes</span><span>${p.due?datefmt(p.due):'Sem prazo'}</span></div></article>`).join('')}</section>`).join('')}</div><div class="table-footer">Arraste para organizar. Conclusão e impedimentos abrem o formulário para registrar as informações necessárias.</div>`;
const groups=[...new Set(rows.map(p=>dep(p.departmentId)?.name||'Secretaria a definir'))];return `<div class="board-scroll">${groups.map(name=>{const list=rows.filter(p=>(dep(p.departmentId)?.name||'Secretaria a definir')===name);return `<section class="board-group"><div class="board-group-head"><b>${esc(name)}</b><span>${list.length} projetos</span></div><div class="table-wrap"><table class="table monday-board"><thead><tr><th>Projeto / entrega</th><th>Responsável</th><th>Situação</th><th>Prazo</th><th>Avanço físico</th><th>Documentação</th><th></th></tr></thead><tbody>${list.map(projectRow).join('')}</tbody></table></div></section>`}).join('')}</div><div class="table-footer"><span>${rows.length} iniciativas exibidas</span><span>“A validar” preserva a distinção entre notícia, medição e entrega aceita.</span></div>`;}
function avatar(name){return `<span class="person-avatar" title="${esc(name||'Responsável a definir')}">${name?esc(name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()):icon('people')}</span>`;}
function projectRow(p){const owner=person(p.ownerId),short=researchLabel(p.researchStatus);return `<tr><td class="table-title"><button data-action="open-project" data-id="${p.id}">${esc(p.title)}</button><small>${p.commitmentIds.map(i=>'PG-'+String(i).padStart(3,'0')).join(' · ')}</small></td><td><button class="owner-cell" data-action="${canEdit(p)?'edit-project':'open-project'}" data-id="${p.id}">${avatar(owner?.name)}<span>${esc(owner?.name||'A definir')}</span></button></td><td class="board-status">${canEdit(p)?`<select class="status-select status-${p.status}" data-quick-status="${p.id}" aria-label="Situação de ${esc(p.title)}">${['em_validacao','planejado','em_andamento','bloqueado','concluido'].map(st=>`<option value="${st}" ${st===p.status?'selected':''}>${statusNames[st]}</option>`).join('')}</select>`:badge(statusNames[p.status],tone(p.status))}</td><td class="nowrap">${p.due?datefmt(p.due):'<span class="blank-value">Definir prazo</span>'}${overdue(p)?'<br>'+badge('Vencido','red'):''}</td><td>${progressCell(p)}</td><td><button class="doc-count" data-action="open-project" data-id="${p.id}">${icon('link')}${p.evidence.length} fontes</button>${short?`<small class="research-small">${esc(short)}</small>`:''}</td><td><button class="icon-btn" data-action="open-project" data-id="${p.id}" aria-label="Abrir ${esc(p.title)}">${icon('chevron')}</button></td></tr>`;}

function departments(){return heading('Cada secretaria, suas entregas.','Os oito eixos do plano são a organização inicial. Os nomes e responsáveis podem ser ajustados nos cadastros.','')+`<div class="cards-grid">${store.state.departments.map(d=>{const cs=store.state.commitments.filter(c=>c.departmentId===d.id),ps=active().filter(p=>p.departmentId===d.id);return `<section class="panel department-card"><span class="dept-icon">${icon('departments')}</span><h2>${esc(d.name)}</h2><p class="muted small">${esc(d.leader||'Titular / ponto focal a definir')}</p><div class="dept-stats"><span><b class="mono">${cs.length}</b>Compromissos</span><span><b class="mono">${ps.length}</b>Projetos</span><span><b class="mono">${ps.filter(p=>overdue(p)||p.status==='bloqueado').length}</b>Com atenção</span></div><div class="actions">${btn('Ver compromissos','filter-department','secondary',`data-id="${d.id}"`)}</div></section>`}).join('')}</div>`;}
function projectDetail(){const p=store.state.projects.find(p=>p.id===detailId);if(!p)return empty('Projeto não encontrado','Abra a lista de projetos para continuar.',btn('Ver projetos','go-projects','secondary'));const updates=store.state.updates.filter(u=>u.projectId===p.id),cs=store.state.commitments.filter(c=>p.commitmentIds.includes(c.id));
 const milestoneHTML=p.milestones.length?p.milestones.map(m=>`<div class="milestone"><span class="check ${m.done?'done':''}">${m.done?'✓':''}</span><div><strong>${esc(m.title)}</strong><small>${m.due?datefmt(m.due):'Sem prazo'} · ${esc(person(m.ownerId||p.ownerId)?.name||'Responsável a definir')} · peso ${m.weight}</small></div><span style="margin-left:auto">${badge(m.done?'Concluído':'Pendente',m.done?'green':'neutral')}</span></div>`).join(''):empty('Tarefas ainda não definidas','Adicione as etapas verificáveis para calcular o avanço pelas entregas.',canEdit(p)?btn('Definir tarefas','edit-project','secondary',`data-id="${p.id}"`):'','flag');
 return `<a class="back" href="#projects">${icon('back')} Todos os projetos</a>`+heading(p.title,p.objective||'Defina o objetivo e as entregas esperadas deste projeto.',canEdit(p)?btn(icon('edit')+'Atualizar projeto','edit-project','',`data-id="${p.id}"`):'','Projeto · '+(dep(p.departmentId)?.name||'Responsabilidade individual'))+`<div class="facts"><div class="fact">Situação<b>${badge(statusNames[p.status],tone(p.status))}${p.archived?badge('Arquivado'):''}</b></div><div class="fact">Responsável<b>${esc(person(p.ownerId)?.name||'A definir')}</b></div><div class="fact">Início previsto<b>${p.start?datefmt(p.start):'A definir'}</b></div><div class="fact">Conclusão prevista<b>${datefmt(p.due)} ${overdue(p)?badge('Vencido','red'):''}</b></div></div>${p.blocker?`<div class="notice warning">${icon('alert')}<p><b>Impedimento informado:</b> ${esc(p.blocker)}</p></div>`:''}<div class="grid"><div>${panel('Tarefas e entregas','Avanço calculado pelos pesos dos marcos; sem marcos, informado pelo responsável.',milestoneHTML)}<div style="height:20px"></div>${panel('Atualizações de acompanhamento','Registros feitos pelos responsáveis pelo projeto.',updates.length?`<div class="timeline">${updates.map(u=>`<div class="timeline-item"><small>${dateTime(u.date)} · ${esc(u.author)}</small><p>${esc(u.text)}</p>${badge(u.progress===null?'Sem medição física':u.progress+'% de avanço','blue')}</div>`).join('')}</div>`:empty('Registre a primeira atualização','Ao atualizar o projeto, descreva o que avançou, o próximo passo e eventuais impedimentos.',canEdit(p)?btn('Registrar atualização','edit-project','secondary',`data-id="${p.id}"`):'','history'))}</div><div>${panel('Execução do projeto','',`<div class="progress-large mono">${p.progress===null?'A medir':p.progress+'%'}</div><div class="track"><span style="width:${p.progress===null?'0%':p.progress+'%'}"></span></div><p class="muted small" style="margin-top:13px">${p.progress===null?'Sem medição física validada. As referências documentam fatos e etapas, não um percentual de execução.':p.milestones.length?'Calculado pelos marcos concluídos.':'Avanço informado pelo responsável.'}</p><div class="fact" style="margin-top:22px">Próxima ação<b>${esc(p.nextAction||'Ainda não informada')}</b></div><div class="facts" style="grid-template-columns:1fr 1fr;margin:22px 0 0"><div class="fact">Orçamento previsto<b>${p.budget?brl(p.budget):'Não informado'}</b></div><div class="fact">Realizado informado<b>${p.spent?brl(p.spent):'Não informado'}</b></div></div>`)}<div style="height:20px"></div>${panel('Compromissos vinculados','Este projeto contribui para:',cs.map(c=>`<button class="btn ghost" style="white-space:normal;text-align:left;justify-content:flex-start;margin-bottom:8px" data-action="open-commitment" data-id="${c.id}">#${String(c.id).padStart(2,'0')} · ${esc(c.title)}</button>`).join(''))}<div style="height:20px"></div>${panel('Evidências','Links e documentos de comprovação.',p.evidence.length?p.evidence.map(e=>`<div class="source-item"><a href="${esc(e.url)}" target="_blank" rel="noopener">${icon('link')} ${esc(e.title)}</a>${e.dateText?`<small>${esc(e.dateText)} · ${esc(e.kind||'Referência documental')}</small>`:''}</div>`).join(''):empty('Sem evidências registradas','Inclua links para comprovar as entregas antes de concluir o projeto.','','link'))}</div></div>${projectHistory(p)}<p class="export-note">Última atualização: ${dateTime(p.updatedAt)} · ${esc(p.updatedBy)}. ${admin()?`<button class="btn ghost" data-action="archive-project" data-id="${p.id}">${p.archived?'Reativar':'Arquivar'} projeto</button>`:''}</p>`;
}
function eventRow(m){return `<div class="date-row"><div class="date-box mono">${datefmt(m.due).slice(0,5)}<small>${m.due.slice(0,4)}</small></div><div><button class="btn ghost" style="white-space:normal;text-align:left;justify-content:flex-start;padding:0" data-action="open-project" data-id="${m.projectId}">${esc(m.title)}</button><p>${esc(m.project)} · ${esc(dep(m.departmentId)?.name||'Responsável individual')}</p></div>${badge(m.due<today()?'Prazo vencido':'Previsto',m.due<today()?'red':'blue')}</div>`;}
function agenda(){const events=active().flatMap(p=>[...(p.due&&p.status!=='concluido'?[{id:p.id,title:'Conclusão do projeto',due:p.due,project:p.title,projectId:p.id,departmentId:p.departmentId}]:[]),...p.milestones.filter(m=>m.due&&!m.done).map(m=>({...m,project:p.title,projectId:p.id,departmentId:p.departmentId}))]).sort((a,b)=>a.due.localeCompare(b.due));return heading('Agenda de entregas.','Prazos de projetos e marcos ainda pendentes, ordenados por data.',btn(icon('print')+'Imprimir','print','secondary'))+`<section class="panel">${events.length?events.map(eventRow).join(''):empty('Nenhuma entrega com data definida','Cadastre projetos e estabeleça os prazos dos marcos para organizar a agenda.',createButton(),'calendar')}</section>`;}
function alerts(){const ps=active(),missing=store.state.commitments.filter(c=>!related(c).length),alerts=ps.filter(p=>overdue(p)||p.status==='bloqueado'||stale(p)||!p.due);return heading('O que precisa de atenção.','Impedimentos, prazos, atualização dos projetos e compromissos ainda sem iniciativas.',btn(icon('download')+'Exportar relatório','export','secondary'))+`<div class="kpis">${kpi('Prazos vencidos',ps.filter(overdue).length,'Projetos não concluídos','clock')}${kpi('Projetos bloqueados',ps.filter(p=>p.status==='bloqueado').length,'Impedimentos informados','alert')}${kpi('Sem atualização há 15 dias',ps.filter(stale).length,'Projetos ativos não concluídos','history')}${kpi('Compromissos sem projeto',missing.length,'Precisam de estruturação','link')}</div>${alerts.length?`<section class="panel"><div class="panel-head"><h2>Projetos para revisão</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Projeto</th><th>Responsabilidade</th><th>Motivo</th><th>Próxima ação</th></tr></thead><tbody>${alerts.map(p=>`<tr><td class="table-title"><button data-action="open-project" data-id="${p.id}">${esc(p.title)}</button></td><td>${esc(dep(p.departmentId)?.name||person(p.ownerId)?.name)}</td><td>${overdue(p)?badge('Prazo vencido','red'):''} ${p.status==='bloqueado'?badge('Bloqueado','red'):''} ${stale(p)?badge('Atualização pendente','amber'):''} ${!p.due?badge('Sem prazo','amber'):''}</td><td>${esc(p.nextAction||'A definir')}</td></tr>`).join('')}</tbody></table></div></section>`:''}${missing.length?`<div class="notice warning">${icon('info')}<p><b>${missing.length} compromissos ainda sem projetos.</b> A ausência de cadastro neste sistema não significa que a Prefeitura não tenha iniciativas em execução. ${btn('Revisar compromissos','missing-commitments','ghost')}</p></div>`:''}`;}
function history(){return heading('Histórico de acompanhamento.','Quem alterou, o que foi registrado e quando. Os registros são mantidos pelo servidor.',btn(icon('download')+'Exportar dados','export','secondary'))+panel('Registros de gestão',`${store.state.history.length} eventos registrados`,store.state.history.length?`<div class="timeline">${store.state.history.map(h=>`<div class="timeline-item"><small>${dateTime(h.date)} · ${esc(h.actor)}</small><p>${esc(h.message)}</p></div>`).join('')}</div>`:empty('O histórico começa com a primeira ação','Cadastros, alterações de projetos e validações de compromissos aparecerão aqui.','','history'));}
function settings(){if(!admin())return empty('Acesso restrito','Esta área é reservada à administração do SIGPMF.');const s=store.state;return heading('Responsáveis pelos projetos.','Use os usuários e vínculos de secretaria já administrados no SIGPMF.',btn(icon('plus')+'Novo responsável','new-person'))+panel('Pontos focais','Cadastrar um responsável não cria uma conta nem concede permissões.',s.people.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Secretaria</th><th>Contato</th><th></th></tr></thead><tbody>${s.people.map(p=>`<tr><td><b>${esc(p.name)}</b><br><small class="muted">${esc(p.position)}</small></td><td>${esc(dep(p.departmentId)?.name||'Sem vínculo fixo')}</td><td>${esc(p.email||'Não informado')}</td><td>${btn('Editar','edit-person','ghost',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Cadastre os pontos focais','Defina quem responde por cada projeto, usando o e-mail da conta SIGPMF quando houver.',btn('Adicionar responsável','new-person','secondary'),'people'))+`<div class="notice">${icon('lock')}<p>As secretarias e permissões são as do SIGPMF. Administrações de contas e vínculos continuam em <a href="/ti/acesso-secretaria">Acesso por secretaria</a>. Operadores atualizam projetos do seu escopo ou atribuídos ao seu e-mail; o vínculo TODAS permite o acompanhamento do gabinete.</p></div>`;}

function showDialog(id,title,body,foot=''){root.querySelectorAll('dialog[open]').forEach(d=>d.close());const el=$('#'+id);if(el.open)el.close();el.innerHTML=`<div class="dialog-head"><h2 id="${id==='drawer'?'dialog-title':'modal-title'}">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" data-dialog="${id}" aria-label="Fechar">${icon('close')}</button></div>${body}${foot}`;el.showModal();}
const field=(label,name,value='',type='text',extra='',wide=false)=>`<label class="field ${wide?'wide':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const selectField=(label,name,items,value='',extra='',wide=false)=>`<label class="field ${wide?'wide':''}">${label}<select name="${name}" ${extra}>${items.map(([id,n])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
const textField=(label,name,value='',wide=true)=>`<label class="field ${wide?'wide':''}">${label}<textarea name="${name}" maxlength="5000">${esc(value)}</textarea></label>`;
const formFoot=(id,label='Salvar')=>`<div class="dialog-foot">${btn('Cancelar','close-dialog','secondary',`data-dialog="${id}"`)}<button class="btn" type="submit" form="edit-form">${label}</button></div>`;
function milestoneFormRow(m={}){return `<div class="inline-fields milestone-form" data-id="${esc(m.id||'')}"><label class="field">Tarefa / entrega<input class="m-title" value="${esc(m.title||'')}" placeholder="Ex.: entrega e aceite da etapa" required maxlength="200"></label><label class="field">Prazo<input class="m-due" type="date" value="${esc(m.due||'')}"></label><label class="field">Responsável<select class="m-owner"><option value="">Herdar do projeto</option>${store.state.people.filter(x=>!x.archived).map(x=>`<option value="${x.id}" ${m.ownerId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">Peso<input class="m-weight" type="number" value="${m.weight||1}" min="1" max="1000" required></label><button class="icon-btn" type="button" data-action="remove-line" aria-label="Remover tarefa">${icon('close')}</button><label class="milestone-done"><input class="m-done" type="checkbox" ${m.done?'checked':''}> Concluída</label></div>`;}
function evidenceFormRow(e={}){return `<div class="inline-fields evidence-fields evidence-form" data-id="${esc(e.id||'')}"><input class="e-title" aria-label="Título da evidência" value="${esc(e.title||'')}" placeholder="Nome do documento / evidência" maxlength="200"><input class="e-url" aria-label="Endereço da evidência" type="url" value="${esc(e.url||'')}" placeholder="https://…" required><button class="icon-btn" type="button" data-action="remove-line" aria-label="Remover evidência">${icon('close')}</button></div>`;}
function projectForm(id='',commitmentId=''){const p=id?store.state.projects.find(x=>x.id===id):null;if(p&&!canEdit(p))return toast('Seu perfil não pode alterar este projeto.',true);const defaults=p||{title:'',departmentId:commitmentId?store.state.commitments.find(c=>c.id===Number(commitmentId))?.departmentId:'',ownerId:'',commitmentIds:commitmentId?[Number(commitmentId)]:[],status:'planejado',priority:'media',progress:null,milestones:[],evidence:[]};
 const allowed=store.state.departments.filter(d=>admin()||store.user.departmentIds.includes(d.id));const people=store.state.people;
 const checks=store.state.commitments.map(c=>`<label class="check-item ${defaults.commitmentIds.includes(c.id)?'selected':''}"><input type="checkbox" name="commitmentIds" value="${c.id}" ${defaults.commitmentIds.includes(c.id)?'checked':''}><span><b class="mono small">#${String(c.id).padStart(2,'0')}</b> ${esc(c.title)}<small style="display:block;color:var(--muted)">${esc(c.area)}</small></span></label>`).join('');
 const body=`<form id="edit-form" data-form="project" data-id="${esc(id)}"><div class="dialog-body"><div class="form-grid">${field('Nome do projeto *','title',defaults.title,'text','required maxlength="200"',true)}${textField('Objetivo e entregas esperadas','objective',defaults.objective)}${selectField('Secretaria executora','departmentId',[['','Sem secretaria · atribuir responsável'],...allowed.map(d=>[d.id,d.name])],defaults.departmentId)}${selectField('Responsável / ponto focal','ownerId',[['','A definir'],...people.map(p=>[p.id,p.name])],defaults.ownerId)}<p class="muted small field wide" style="font-weight:400">Informe pelo menos uma secretaria ou um responsável. ${!people.length?'Cadastre os pontos focais em Cadastros e acessos.':''}</p>${selectField('Situação','status',['em_validacao','planejado','em_andamento','bloqueado','concluido'].map(s=>[s,statusNames[s]]),defaults.status)}${selectField('Prioridade','priority',[['alta','Alta'],['media','Média'],['baixa','Baixa']],defaults.priority)}${field('Início previsto','start',defaults.start,'date')}${field('Conclusão prevista','due',defaults.due,'date')}${field('Orçamento previsto (R$)','budget',defaults.budget||0,'number','min="0" step="0.01"')}${field('Realizado informado (R$)','spent',defaults.spent||0,'number','min="0" step="0.01"')}</div><div class="form-section"><h3>Compromissos vinculados *</h3><p>Selecione um ou mais itens para os quais o projeto contribui.</p><input id="commitment-search" aria-label="Buscar compromissos para vincular" placeholder="Filtrar os 70 compromissos…" style="margin-bottom:10px"><div class="check-list" id="commitment-checks">${checks}</div></div><div class="form-section"><h3>Tarefas, prazos e avanço</h3><p>Com marcos, o avanço é calculado pelos pesos das entregas concluídas. Sem marcos, use o avanço informado.</p><div id="milestone-list">${defaults.milestones.map(milestoneFormRow).join('')}</div>${btn(icon('plus')+'Adicionar tarefa','add-milestone','secondary','type="button"')}<div style="margin-top:15px">${field('Avanço físico (%) · deixe vazio se ainda não houver medição','progress',defaults.progress,'number','min="0" max="100" placeholder="Não medido"')}</div></div><div class="form-section"><h3>Evidências de entrega</h3><p>Use links HTTP/HTTPS para documentos e registros acessíveis à gestão.</p><div id="evidence-list">${defaults.evidence.map(evidenceFormRow).join('')}</div>${btn(icon('plus')+'Adicionar evidência','add-evidence','secondary','type="button"')}</div><div class="form-section"><h3>Acompanhamento</h3><div class="form-grid">${textField('Próxima ação','nextAction',defaults.nextAction)}${textField('Impedimento / decisão necessária','blocker',defaults.blocker)}${textField('Registrar atualização no histórico do projeto','updateNote','')}</div><p class="muted small" style="margin-top:12px">Para concluir o projeto, informe 100% de avanço e pelo menos uma evidência. A validação dos compromissos é feita separadamente pelo gabinete ou pela gestão.</p></div><p class="form-error" role="alert"></p></div></form>`;
 showDialog('drawer',p?'Atualizar projeto':'Novo projeto',body,formFoot('drawer',p?'Salvar atualização':'Criar projeto'));}
function commitmentDialog(id){const c=store.state.commitments.find(x=>x.id===Number(id));if(!c)return;const ps=related(c);const canValidate=admin()||store.user.role==='prefeito';showDialog('drawer',`Compromisso #${String(c.id).padStart(2,'0')}`,`<div class="dialog-body"><div class="eyebrow">${esc(c.area)} · Plano, página ${c.page}</div><h2 style="font-size:23px;margin-bottom:18px">${esc(c.title)}</h2>${badge(statusNames[c.validation],tone(c.validation))}${c.validation==='a_validar'&&c.reviewReason?`<div class="notice warning">${esc(c.reviewReason)}</div>`:''}<div class="form-section"><h3>Projetos vinculados (${ps.length})</h3>${ps.length?ps.map(p=>`<div class="source-item"><button class="btn ghost" style="white-space:normal;padding-left:0;text-align:left" data-action="open-project" data-id="${p.id}">${esc(p.title)}</button><small>${esc(dep(p.departmentId)?.name||person(p.ownerId)?.name||'Responsável individual')} · ${p.progress===null?'A medir':p.progress+'%'} · ${statusNames[p.status]} · Prazo: ${datefmt(p.due)} · ${p.milestones.filter(m=>m.done).length}/${p.milestones.length} tarefas concluídas</small></div>`).join(''):empty('Este compromisso ainda não tem projeto','Cadastre uma iniciativa ou vincule um projeto já existente.','','projects')}<div class="actions" style="margin-top:15px">${createButton(c.id)}${!['prefeito','leitura'].includes(store.user.role)&&active().length?btn(icon('link')+'Vincular projeto existente','link-project','secondary',`data-id="${c.id}"`):''}</div></div><div class="form-section"><h3>Critério de cumprimento e validação</h3><p>O avanço dos projetos apoia o acompanhamento. O cumprimento do compromisso exige análise própria.</p>${canValidate?`<form id="edit-form" data-form="commitment" data-id="${c.id}"><div class="form-grid">${selectField('Secretaria de referência','departmentId',[['','A definir'],...store.state.departments.map(d=>[d.id,d.name])],c.departmentId,'',true)}${textField('Critério de cumprimento esperado','acceptanceCriteria',c.acceptanceCriteria)}${selectField('Situação validada pela gestão','validation',['a_validar','planejada','em_andamento','parcial','cumprida'].map(s=>[s,statusNames[s]]),c.validation,'',true)}${textField('Justificativa da avaliação','validationNote',c.validationNote)}${field('Link da evidência de cumprimento','validationEvidence',c.validationEvidence,'url','placeholder="https://…"',true)}</div><p class="form-error" role="alert"></p><button class="btn" type="submit">Salvar avaliação</button></form>`:`<p>${esc(c.acceptanceCriteria||'Critério ainda não definido pela gestão.')}</p><p>${esc(c.validationNote||'Sem avaliação registrada.')}</p>`}</div><div class="form-section"><h3>Pesquisa documental inicial</h3><p class="muted small">Referência de 23/11/2026. Não é uma avaliação oficial da secretaria.</p>${badge(c.researchStatus,c.researchStatus==='Entrega comprovada'?'green':'neutral')}<p style="font-size:14px;margin-top:13px">${esc(c.researchNote)}</p>${c.sources.map(s=>`<div class="source-item"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><small>${esc(s.kind)} · ${esc(s.date)}</small></div>`).join('')}<p class="muted small" style="margin-top:12px">Vínculo com TI no levantamento: ${esc(c.ti)}</p></div></div>`);}
function personForm(id=''){const p=store.state.people.find(x=>x.id===id)||{};showDialog('modal',id?'Editar responsável':'Novo responsável',`<form id="edit-form" data-form="person" data-id="${id}"><div class="dialog-body"><div class="form-grid">${field('Nome *','name',p.name,'text','required maxlength="150"',true)}${field('Cargo / função','position',p.position,'text','maxlength="150"',true)}${selectField('Secretaria','departmentId',[['','Sem vínculo fixo'],...store.state.departments.map(d=>[d.id,d.name])],p.departmentId,'',true)}${field('E-mail','email',p.email,'email','',true)}</div><p class="muted small" style="margin-top:13px">Cadastrar um responsável não cria acesso. O acesso é configurado separadamente.</p><p class="form-error" role="alert"></p></div></form>`,formFoot('modal'));}
function linkProject(id){const c=store.state.commitments.find(x=>x.id===Number(id));const options=active().filter(p=>canEdit(p)&&!p.commitmentIds.includes(c.id));if(!options.length)return toast('Não há outro projeto disponível para vincular. Crie um projeto ou revise seu escopo de acesso.');showDialog('modal','Vincular projeto existente',`<form id="edit-form" data-form="link" data-id="${c.id}"><div class="dialog-body"><p class="muted small">O mesmo projeto pode contribuir para vários compromissos.</p>${selectField('Projeto','projectId',options.map(p=>[p.id,p.title]),options[0].id)}<p class="form-error" role="alert"></p></div></form>`,formFoot('modal','Vincular projeto'));}
function exportData(){const snapshot={generatedAt:new Date().toISOString(),researchCutoff:'2026-11-23',...store.state};delete snapshot.members;const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sigplan-franca-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Relatório de dados exportado. Para uma versão de reunião, use a impressão do painel.');}
async function submit(event){const form=event.target;if(!form.matches('form[data-form]'))return;event.preventDefault();const fd=new FormData(form),data=Object.fromEntries(fd),kind=form.dataset.form,id=form.dataset.id;if(id)data.id=id;
 try{
  let action=kind+'.save';
  if(kind==='project'){data.commitmentIds=fd.getAll('commitmentIds').map(Number);data.milestones=[...form.querySelectorAll('.milestone-form')].map(r=>({id:r.dataset.id,title:r.querySelector('.m-title').value,ownerId:r.querySelector('.m-owner').value,due:r.querySelector('.m-due').value,weight:Number(r.querySelector('.m-weight').value),done:r.querySelector('.m-done').checked}));data.evidence=[...form.querySelectorAll('.evidence-form')].map(r=>({id:r.dataset.id,title:r.querySelector('.e-title').value,url:r.querySelector('.e-url').value}));}
  if(kind==='member')data.departmentIds=fd.getAll('departmentIds');
  if(kind==='link'){action='project.save';const p=store.state.projects.find(p=>p.id===data.projectId);Object.assign(data,p,{commitmentIds:[...p.commitmentIds,Number(id)],updateNote:`Vinculado ao compromisso #${id}.`});}
  if(await mutate(action,data)){const parent=form.closest('dialog');parent?.close();render();toast('Registro salvo com sucesso.');}
 }catch(err){const box=form.querySelector('.form-error');if(box)box.textContent=err.message;else toast(err.message,true);}
}
root.addEventListener('submit',submit);
const inputHandler=event=>{const el=event.target;if(el.id==='week-from'||el.id==='week-to'){if(el.id==='week-from')weekFrom=el.value;else weekTo=el.value;render();return;}if(el.dataset.filter){filters[el.dataset.filter]=el.value;page=1;renderRows();}if(el.id==='commitment-search'){const value=el.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();root.querySelectorAll('#commitment-checks .check-item').forEach(r=>r.hidden=!r.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(value));}if(el.name==='commitmentIds')el.closest('.check-item').classList.toggle('selected',el.checked);};
root.addEventListener('input',inputHandler);
const clickHandler=async event=>{const deptFilter=event.target.closest('[data-dept-filter]');if(deptFilter){event.preventDefault();navTo('commitments');setTimeout(()=>{filters.department=deptFilter.dataset.deptFilter;const select=$('[data-filter=department]');if(select)select.value=filters.department;renderRows();},0);return;}
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const id=b.dataset.id,a=b.dataset.action;
 try{switch(a){case'reload':await reload();render();toast('Dados atualizados.');break;case'new-project':projectForm('',id);break;case'edit-project':projectForm(id);break;case'open-project':root.querySelectorAll('dialog[open]').forEach(d=>d.close());navTo('project',id);break;case'open-commitment':commitmentDialog(id);break;case'go-commitments':navTo('commitments');break;case'go-projects':navTo('projects');break;case'go-weekly':navTo('weekly');break;case'board-mode':boardMode=b.dataset.mode;render();break;case'board-status':navTo('projects');setTimeout(()=>{filters.status=b.dataset.status;const select=$('[data-filter=status]');if(select)select.value=filters.status;renderRows();},0);break;case'go-alerts':navTo('alerts');break;case'close-dialog':$('#'+(b.dataset.dialog||'drawer')).close();break;case'new-person':personForm();break;case'edit-person':personForm(id);break;case'add-milestone':$('#milestone-list').insertAdjacentHTML('beforeend',milestoneFormRow());break;case'add-evidence':$('#evidence-list').insertAdjacentHTML('beforeend',evidenceFormRow());break;case'remove-line':b.closest('.inline-fields').remove();break;case'link-project':linkProject(id);break;case'prev':page--;renderRows();break;case'next':page++;renderRows();break;case'clear-filters':filters={q:'',department:'',status:'',research:'',scope:'all'};render();break;case'export':exportData();break;case'print':window.print();break;case'filter-department':case'missing-commitments':navTo('commitments');setTimeout(()=>{if(a==='filter-department'){filters.department=id;const select=$('[data-filter=department]');if(select)select.value=id;}else{filters.scope='missing';const select=$('[data-filter=scope]');if(select)select.value='missing';}renderRows();},0);break;case'archive-project':if(confirm('Arquivar ou reativar este projeto? O histórico será preservado.')){if(await mutate('project.archive',{id})){render();toast('Projeto atualizado.');}}break;}
 }catch(err){toast(err.message,true);}
};
root.addEventListener('click',clickHandler);
window.addEventListener('hashchange',route);
(async()=>{try{await reload();if(!disposed)route();}catch(e){if(disposed)return;$('#app').innerHTML=`<main class="startup"><h1>Plano de Governo</h1><p>${esc(e.message)}</p><button class="btn" data-action="reload">Tentar novamente</button></main>`;}})();

function shiftDay(day,delta){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+delta);return d.toISOString().slice(0,10);}
function researchLabel(status){return {'Entrega comprovada':'Entrega identificada','Ampliação informada':'Ampliação informada','Em andamento / parcial':'Etapas documentadas','Continuidade; expansão não comprovada':'Serviço existente'}[status]||'';}
function uniqueDocuments(){const map=new Map();for(const e of store.state.documentaryEvents||[])if(!map.has(e.url))map.set(e.url,e);return [...map.values()];}
function atDate(projectId,day){const cutoff=Date.parse(day+'T23:59:59-03:00');return (store.state.snapshots||[]).filter(x=>x.projectId===projectId&&Date.parse(x.date)<=cutoff).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date))[0]||null;}
function difference(a,b){if(a?.progress===null||b?.progress===null||!a||!b)return '<span class="muted small">Sem duas medições</span>';const delta=b.progress-a.progress;return badge(`${delta>0?'+':''}${delta} p.p.`,delta>0?'green':delta<0?'amber':'neutral');}
function reta(vals){const n=vals.length;if(n<2)return vals.slice();let sx=0,sy=0,sxx=0,sxy=0;vals.forEach((y,x)=>{sx+=x;sy+=y;sxx+=x*x;sxy+=x*y});const den=n*sxx-sx*sx||1,a=(n*sxy-sx*sy)/den,b=(sy-a*sx)/n;return vals.map((_,i)=>a*i+b);}
function documentChart(end=today()){const docs=uniqueDocuments().filter(e=>e.date);const values=Array.from({length:8},(_,i)=>{const to=shiftDay(end,-7*(7-i)),from=shiftDay(to,-6);return{from,to,n:docs.filter(e=>e.date>=from&&e.date<=to).length};});const max=Math.max(...values.map(x=>x.n),1);if(!values.some(x=>x.n))return `<div class="notice"><p>Não há referências com data precisa nas oito semanas até ${datefmt(end)}. Consulte o histórico dos projetos para os registros anteriores.</p></div>`;return `<div class="week-chart"><svg viewBox="0 0 640 210" role="img" aria-label="Publicações distintas por semana nas oito semanas até ${datefmt(end)}"><line x1="35" y1="170" x2="630" y2="170" stroke="currentColor" opacity=".15"/><text x="10" y="28" class="axis-label">${max}</text><text x="15" y="173" class="axis-label">0</text>${values.map((v,i)=>{const x=55+i*72,h=120*v.n/max;return `<g><title>${datefmt(v.from)} a ${datefmt(v.to)}: ${v.n} documentos</title><rect x="${x}" y="${170-h}" width="32" height="${Math.max(h,1)}" rx="4" class="document-bar"/><text x="${x+16}" y="${160-h}" text-anchor="middle" class="bar-number">${v.n}</text><text x="${x+16}" y="194" text-anchor="middle" class="axis-label">${datefmt(v.to).slice(0,5)}</text></g>`}).join('')}${(()=>{const ys=reta(values.map(v=>v.n));return `<polyline class="tendencia-linha" fill="none" stroke="#1C1917" stroke-dasharray="5 4" stroke-width="2" points="${values.map((v,i)=>`${55+i*72+16},${170-120*Math.max(ys[i],0)/max}`).join(' ')}"/>`})()}</svg><p class="chart-legend"><i class="lg-serie"></i> Publicações <i class="lg-tendencia"></i> Tendência</p></div><p class="chart-caption">Eixo horizontal: semana encerrada em (dia/mês). Vertical: publicações distintas (un.). Fonte: Pesquisa documental · atualizado em ${datefmt((docs.map(e=>e.date).sort().at(-1))||end)}. Datas de referência nas fontes; cada URL contada uma vez. ${uniqueDocuments().filter(e=>!e.date).length} fontes sem data precisa ficam fora do gráfico.</p>`;}
function progressChart(p){const series=(store.state.snapshots||[]).filter(x=>x.projectId===p.id&&x.progress!==null).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));if(series.length<2)return `<div class="measurement-prompt">${icon('target')}<div><b>${series.length?'Primeira medição registrada':'A história física começa com uma medição'}</b><p>${series.length?'Mais uma atualização permitirá comparar o avanço.':'As fontes já mostram o que foi publicado. Para medir execução, registre o avanço físico ou conclua marcos verificáveis.'}</p></div></div>`;const min=Date.parse(series[0].date),range=Math.max(1,Date.parse(series.at(-1).date)-min);const pts=series.map(x=>({x:42+550*(Date.parse(x.date)-min)/range,y:150-1.2*x.progress,...x}));return `<svg class="progress-chart" viewBox="0 0 640 200" role="img" aria-label="Avanço físico registrado do projeto, em porcentagem, ao longo das datas de medição"><line x1="42" y1="150" x2="610" y2="150" class="chart-grid"/><line x1="42" y1="30" x2="610" y2="30" class="chart-grid"/><text x="4" y="34" class="axis-label">100%</text><text x="16" y="154" class="axis-label">0%</text><polyline points="${pts.map(x=>x.x+','+x.y).join(' ')}" class="progress-line"/>${(()=>{const ys=reta(series.map(x=>x.progress));return `<polyline class="tendencia-linha" fill="none" stroke="#1C1917" stroke-dasharray="5 4" stroke-width="2" points="${pts.map((p,i)=>p.x+','+(150-1.2*ys[i])).join(' ')}"/>`})()}${pts.map((p,i)=> (pts.length<=6 || i%Math.ceil(pts.length/6)===0 || i===pts.length-1) ? `<text x="${p.x}" y="${p.y-8}" text-anchor="middle" class="bar-number">${p.progress}%</text>` : '').join('')}${pts.map(x=>`<circle cx="${x.x}" cy="${x.y}" r="4" class="progress-point"><title>${dateTime(x.date)}: ${x.progress}% · ${esc(x.author)}</title></circle>`).join('')}<text x="42" y="183" class="axis-label">${datefmt(series[0].date)}</text><text x="590" y="183" text-anchor="end" class="axis-label">${datefmt(series.at(-1).date)}</text></svg><p class="chart-legend"><i class="lg-serie"></i> Medições <i class="lg-tendencia"></i> Tendência</p><p class="chart-caption">Unidade: %. Avanço físico por data de medição. Fonte: Atualizações de gestão · atualizado em ${datefmt(series.at(-1).date)}. Não deriva das notícias.</p>`;}
function projectHistory(p){const from=weekFrom||shiftDay(today(),-7),to=weekTo||today(),a=atDate(p.id,from),b=atDate(p.id,to);const events=(store.state.documentaryEvents||[]).filter(e=>e.projectId===p.id).sort((x,y)=>(y.date||'').localeCompare(x.date||''));return `<div class="grid">${panel('Evolução do projeto','Medições físicas feitas pela equipe.',progressChart(p))}${panel('Comparação entre períodos',`${datefmt(from)} versus ${datefmt(to)}`,`<div class="comparison-numbers"><div><small>Início do período</small><strong>${a?.progress===null||!a?'Não medido':a.progress+'%'}</strong></div><div><small>Fim do período</small><strong>${b?.progress===null||!b?'Não medido':b.progress+'%'}</strong></div></div><p>${difference(a,b)}</p><p class="muted small">São usadas as últimas medições disponíveis até cada data. ${!a||!b?'O sistema não preenche períodos passados com percentuais estimados.':''}</p>${btn('Escolher períodos','go-weekly','secondary')}`)}</div>${events.length?panel('Linha do tempo documental','Publicações e documentos que sustentam a referência inicial. A data é a indicada na fonte.',`<div class="document-timeline">${events.map(e=>`<article><span>${e.date?datefmt(e.date):'Data a confirmar'}</span><div><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)}</a><small>${esc(e.kind)} · ${esc(e.dateText)}</small><p>${esc(e.summary)}</p></div></article>`).join('')}</div>`):''}`;}
function weekly(){const from=weekFrom||shiftDay(today(),-7),to=weekTo||today();const snapshots=(store.state.snapshots||[]).filter(x=>localDay(x.date)>from&&localDay(x.date)<=to),updated=new Set(snapshots.map(x=>x.projectId)),completed=new Set(snapshots.filter(x=>x.status==='concluido'&&x.previousStatus!=='concluido').map(x=>x.projectId)),docs=uniqueDocuments().filter(e=>e.date&&e.date>from&&e.date<=to);if(from>to)return heading('Evolução semanal.','Compare dois momentos sem perder a referência do que foi efetivamente medido.')+comparisonControls(from,to)+'<div class="notice warning">A data inicial deve ser anterior à data final.</div>';
return heading('O que avançou, semana a semana.','Compare entregas, medições e decisões. O histórico documental e a execução física têm leituras separadas.',btn(icon('print')+'Preparar reunião','print','secondary'))+comparisonControls(from,to)+`<div class="kpis">${kpi('Projetos atualizados',updated.size,'Com registro de gestão no período','history')}${kpi('Conclusões registradas',completed.size,'Transições para concluído no período','check')}${kpi('Documentos no período',docs.length,'Referências distintas com data precisa','link')}${kpi('Projetos com impedimento',active().filter(p=>p.status==='bloqueado').length,'Situação atual da carteira','alert')}</div><div class="grid executive-grid">${panel('Rastro documental por semana','Publicações distintas ligadas às iniciativas; não é execução física.',documentChart(to))}${panel('Resumo para a reunião','Leitura objetiva do período selecionado.',`<ul class="meeting-summary"><li><b>${updated.size} projetos</b> receberam atualização de gestão.</li><li><b>${completed.size} projetos</b> tiveram conclusão registrada.</li><li><b>${docs.length} referências</b> documentais estão datadas no período.</li><li><b>${active().filter(p=>!p.ownerId).length} projetos</b> ainda precisam de ponto focal.</li></ul><p class="muted small">A comparação usa a última observação disponível até cada data, sem retroagir o avanço atual para semanas anteriores.</p>`)}</div><section class="panel"><div class="panel-head"><div><h2>Comparação histórica por projeto</h2><p>${datefmt(from)} versus ${datefmt(to)} · p.p. = pontos percentuais.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Projeto</th><th>Até ${datefmt(from)}</th><th>Até ${datefmt(to)}</th><th>Variação física</th><th>Registros no período</th></tr></thead><tbody>${active().map(p=>{const a=atDate(p.id,from),b=atDate(p.id,to),n=snapshots.filter(x=>x.projectId===p.id).length;return `<tr><td class="table-title"><button data-action="open-project" data-id="${p.id}">${esc(p.title)}</button><small>${esc(dep(p.departmentId)?.name||'Secretaria a definir')}</small></td><td>${a?.progress===null||!a?'Sem medição':a.progress+'%'}</td><td>${b?.progress===null||!b?'Sem medição':b.progress+'%'}</td><td>${difference(a,b)}</td><td>${n?badge(n+' atualizações','blue'):'Sem atualização'}</td></tr>`}).join('')}</tbody></table></div></section>`;}
function comparisonControls(from,to){return `<div class="comparison-controls"><label>Comparar de<input type="date" id="week-from" value="${from}" max="${today()}"></label><label>Até<input type="date" id="week-to" value="${to}" max="${today()}"></label><span>Datas em horário de Brasília · dados de gestão e documentação separados</span></div>`;}
const changeHandler=async event=>{const el=event.target;if(el.dataset.quickStatus){const p=store.state.projects.find(p=>p.id===el.dataset.quickStatus);const value=el.value;if(!p||value===p.status)return;if(['bloqueado','concluido'].includes(value)){projectForm(p.id);const select=$('#drawer select[name=status]');if(select)select.value=value;el.value=p.status;return;}try{if(await mutate('project.save',{...p,status:value,updateNote:`Situação atualizada para ${statusNames[value]}.`})){render();toast('Situação atualizada. Histórico de evolução preservado.');}}catch(e){el.value=p.status;toast(e.message,true);}}};
root.addEventListener('change',changeHandler);
const dragStart=event=>{const el=event.target.closest('[data-project-drag]');if(!el)return;const p=store.state.projects.find(p=>p.id===el.dataset.projectDrag);if(!p||!canEdit(p)){event.preventDefault();return;}event.dataTransfer.setData('text/plain',p.id);};
const dragOver=event=>{if(event.target.closest('[data-drop-status]'))event.preventDefault();};
const drop=async event=>{const column=event.target.closest('[data-drop-status]');if(!column)return;event.preventDefault();const p=store.state.projects.find(p=>p.id===event.dataTransfer.getData('text/plain'));if(!p||!canEdit(p)||p.status===column.dataset.dropStatus)return;const value=column.dataset.dropStatus;if(['bloqueado','concluido'].includes(value)){projectForm(p.id);const select=$('#drawer select[name=status]');if(select)select.value=value;return;}try{if(await mutate('project.save',{...p,status:value,updateNote:`Movido no quadro para ${statusNames[value]}.`})){render();toast('Projeto movido.');}}catch(e){toast(e.message,true);}};
root.addEventListener('dragstart',dragStart);root.addEventListener('dragover',dragOver);root.addEventListener('drop',drop);

return ()=>{disposed=true;clearTimeout(toastTimer);window.removeEventListener('hashchange',route);root.removeEventListener('submit',submit);root.removeEventListener('input',inputHandler);root.removeEventListener('click',clickHandler);root.removeEventListener('change',changeHandler);root.removeEventListener('dragstart',dragStart);root.removeEventListener('dragover',dragOver);root.removeEventListener('drop',drop);root.querySelectorAll('dialog[open]').forEach(d=>d.close());root.innerHTML='';};
}
